:root {
  --bg: #ffffff;
  --text: #111827;
  --muted: #6b7280;
  --border: #e5e7eb;
  --accent: #2563eb;
  --accent-bg: #eff6ff;
  --code-bg: #f3f4f6;
  --panel-bg: #f9fafb;
  --success: #16a34a;
  --warning: #d97706;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  margin: 0;
  padding: 0;
}

body.dark-mode {
  --bg: #0f1117;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --border: #374151;
  --accent: #60a5fa;
  --accent-bg: #1e3a8a;
  --code-bg: #1f2937;
  --panel-bg: #18181b;
  --success: #22c55e;
  --warning: #f59e0b;
}

* {
  box-sizing: border-box;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

header.nav {
  background: var(--panel-bg);
  border-bottom: 1px solid var(--border);
  padding: 1rem;
  margin-bottom: 2rem;
}

header.nav nav {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

header.nav nav > a {
  font-weight: 500;
}

header.nav nav > p {
  margin: 0;
  color: var(--muted);
  font-size: 0.875rem;
}

header.nav nav > button {
  margin-left: auto;
}

main {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 1rem 4rem;
}

.panel {
  background: var(--panel-bg);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.panel h2 {
  margin-top: 0;
  font-size: 1.25rem;
}

.panel h3 {
  margin-top: 0;
  font-size: 1.1rem;
}

.panel p {
  margin: 0.5rem 0;
}

.copy-btn {
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 0.375rem;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  cursor: pointer;
  margin: 0.25rem;
}

.copy-btn:hover {
  opacity: 0.9;
}

.copy-msg {
  color: var(--success);
  font-size: 0.875rem;
  margin: 0 0.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.progress {
  margin: 1rem 0;
}

progress {
  width: 100%;
  height: 0.5rem;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  border: 1px solid var(--border);
  padding: 0.5rem;
  text-align: left;
}

th {
  background: var(--accent-bg);
}

.wake-current {
  background: var(--accent-bg);
  font-weight: bold;
}

.wake-past {
  color: var(--muted);
}

.wake-upcoming {
  color: var(--muted);
}

.local-date-prefix {
  font-size: 0.8em;
  color: var(--muted);
}

footer.footer {
  border-top: 1px solid var(--border);
  padding: 1.5rem;
  margin-top: 2rem;
  text-align: center;
}

footer.footer nav {
  justify-content: center;
}

footer.footer p {
  margin: 0.25rem 0;
  color: var(--muted);
  font-size: 0.875rem;
}

code, pre {
  background: var(--code-bg);
  border-radius: 0.25rem;
  padding: 0.2rem 0.4rem;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: 0.9em;
}

pre {
  padding: 1rem;
  overflow-x: auto;
}

.panel.promise {
  border-style: dashed;
}

@media print {
  header.nav, footer.footer, .copy-btn, .progress, .panel[data-copy], .skip-link {
    display: none !important;
  }
  body {
    background: white;
    color: black;
  }
  .panel {
    border: 1px solid #ccc;
  }
}

@media (prefers-color-scheme: dark) {
  body {
    background: var(--bg);
    color: var(--text);
  }
}
